    slug: "bellini-diffords-recipe",
    name: "Bellini (Difford's recipe)",
    description: "It has long been traditional in Italy to marinade fresh peaches in wine, and the Bellini draws on this tradition by combining prosecco wine with pur\u00e9ed white peaches. Giuseppe Cipriani created this drink at Harry's Bar in Venice in 1945, fourteen years after he opened his tiny place on the edge of the Grand Canal, not far from Piazza San Marco. Cipriani named his cocktail after the 15th-century Venetian painter Giovanni Bellini due to the drink's pink hue and the painter's penchant for using rich pinks on his canvases. Like many other legendary bars around the world, Harry's owes some of its notoriety to being patronised by probably the world's greatest drinker, Ernest Hemingway. It was also the haunt of Sinclair Lewis, Orson Welles, F. Scott Fitzgerald and Dorothy Parker, and con",
