    story: "Caipirinha cocktail history",
    recipe: ["1 &frasl;2 fresh Lime (fresh)", "3 barspoon Superfine/caster sugar", "3 fresh Raspberries", "2 fresh Blackberries", "3 fresh Blueberries (fresh)", "1 fresh Strawberries (fresh)", "60 ml Cacha\u00e7a"],
    technique: "Shaken",
    ingredients: [{"qty": "1", "item": "&frasl;2 fresh Lime (fresh)"}, {"qty": "3", "item": "barspoon Superfine/caster sugar"}, {"qty": "3", "item": "fresh Raspberries"}, {"qty": "2", "item": "fresh Blackberries"}, {"qty": "3", "item": "fresh Blueberries (fresh)"}, {"qty": "1", "item": "fresh Strawberries (fresh)"}, {"qty": "60 ml", "item": "Cacha\u00e7a"}],
    instructions: ["Select and pre-chill a HIGHBALL (MAX 10OZ/300ML) GLASS.", "Prepare garnish of stirrer (spoon, wooden lolly stick or stick cut from sugar cane).", "CUT lime in half (from pole to pole) and then slice one of the halves into eight 3-4mm thick half-moon shaped segments and drop into the base of a robust rocks glass.", "Add 3 bar spoons caster sugar (or \u00bdoz / 15ml sugar syrup 2:1) and MUDDLE.", "Add berries and MUDDLE some more.", "When sure fruit juice is fully extracted and the sugar dissolved, transfer the muddled fruit and sugar into serving glass (preferably a 30cl / 10oz highball glass).", "POUR cacha\u00e7a (stored in the freezer) into the rocks glass (used to muddle) and swirl to rinse glass before pouring cacha\u00e7a into serving glass.", "STIR to ensure all ingredients are well mixed.", "FILL glass with small cubes or cracked ice. (If using large ice cubes, crack (rather than crush) four to five large ice cubes using an ICE TAPPER and drop into serving glass.)", "STIR before topping with more ice.", "Serve with a stirrer (but no straws)."],
