    id: "d0609330-2e40-4777-a0a4-a66685e10b12",
    slug: "black-velvet",
    name: "Black Velvet",
    description: "This black sombre cocktail is said to have originated at London's Brook's Club (or others say, Shelbourne Hotel in Dublin, Ireland) in 1861, immediately after the death of HRH Prince Albert, husband of Queen Victoria, of typhoid fever on 14th December. Devastated, the Queen wore black for the rest of her life so this drink's shrouding of sparkling wine with black stout is most appropriate. However, its origins may date back to an 1830s German cocktail called \"Menschenfreund\" (meaning philanthropist). And perhaps not coincidently, Prince Albert was born in Bavaria, Germany in 1819. This cocktail first appears in a cocktail tome, named \"Champagne Velvet\", in Harry Johnson's 1888 New And Improved Bartender's Manual , written in both English and German. It was enjoyed by the exuberant",
